{"filename":"routes.py","content":"from flask import Blueprint, request, jsonify, abort
from models import get_db

bp = Blueprint("api", __name__)

# Helper to serialize a task row
def _row_to_task(row):
    return {
        "id": row[0],
        "title": row[1],
        "description": row[2],
        "due_date": row[3],
        "status": row[4],
    }

# Validation helpers
def _validate_task_payload(payload, require_all=True):
    required_fields = ["title", "description", "status"]
    errors = []
    for field in required_fields:
        if field not in payload or payload.get(field) in (None, ""):
            errors.append(f"'{field}' is required")
    if "status" in payload and payload.get("status") not in ("pending", "completed"):
        errors.append("status must be 'pending' or 'completed'")
    if errors:
        abort(400, description="; ".join(errors))
    # due_date is optional; if present ensure it's a string
    if "due_date" in payload and payload["due_date"] is not None and not isinstance(payload["due_date"], str):
        abort(400, description="'due_date' must be a string")
    return payload

# GET /tasks (optionally filtered by status)
@bp.route("/tasks", methods=["GET"])
def get_tasks():
    status_filter = request.args.get("status")
    db = get_db()
    cursor = db.cursor()
    if status_filter:
        cursor.execute(
            "SELECT id, title, description, due_date, status FROM task WHERE status = ?",
            (status_filter,),
        )
    else:
        cursor.execute("SELECT id, title, description, due_date, status FROM task")
    rows = cursor.fetchall()
    tasks = [_row_to_task(row) for row in rows]
    return jsonify({"success": True, "data": tasks})

# POST /tasks
@bp.route("/tasks", methods=["POST"])
def create_task():
    if not request.is_json:
        abort(400, description="Request body must be JSON")
    payload = request.get_json()
    _validate_task_payload(payload)
    db = get_db()
    cursor = db.cursor()
    cursor.execute(
        "INSERT INTO task (title, description, due_date, status) VALUES (?, ?, ?, ?)",
        (
            payload["title"],
            payload["description"],
            payload.get("due_date"),
            payload["status"],
        ),
    )
    db.commit()
    task_id = cursor.lastrowid
    return jsonify({"success": True, "data": {"id": task_id}}), 201

# GET /tasks/<int:id>
@bp.route("/tasks/<int:id>", methods=["GET"])
def get_task(id):
    db = get_db()
    cursor = db.cursor()
    cursor.execute(
        "SELECT id, title, description, due_date, status FROM task WHERE id = ?", (id,)
    )
    row = cursor.fetchone()
    if row is None:
        abort(404, description="Task does not exist")
    return jsonify({"success": True, "data": _row_to_task(row)})

# PUT /tasks/<int:id>
@bp.route("/tasks/<int:id>", methods=["PUT"])
def update_task(id):
    if not request.is_json:
        abort(400, description="Request body must be JSON")
    payload = request.get_json()
    _validate_task_payload(payload, require_all=False)
    db = get_db()
    cursor = db.cursor()
    # Ensure task exists
    cursor.execute("SELECT id FROM task WHERE id = ?", (id,))
    if cursor.fetchone() is None:
        abort(404, description="Task does not exist")
    cursor.execute(
        "UPDATE task SET title = ?, description = ?, due_date = ?, status = ? WHERE id = ?",
        (
            payload.get("title"),
            payload.get("description"),
            payload.get("due_date"),
            payload.get("status"),
            id,
        ),
    )
    db.commit()
    return jsonify({"success": True, "data": {"id": id}})

# DELETE /tasks/<int:id>
@bp.route("/tasks/<int:id>", methods=["DELETE"])
def delete_task(id):
    db = get_db()
    cursor = db.cursor()
    cursor.execute("SELECT id FROM task WHERE id = ?", (id,))
    if cursor.fetchone() is None:
        abort(404, description="Task does not exist")
    cursor.execute("DELETE FROM task WHERE id = ?", (id,))
    db.commit()
    return jsonify({"success": True, "data": {"id": id}})

# Additional routes matching alternative placeholder names in the contract
@bp.route("/tasks/<int:item_id>", methods=["GET"])
def get_task_alt(item_id):
    return get_task(item_id)

@bp.route("/tasks/<int:item_id>", methods=["PUT"])
def update_task_alt(item_id):
    return update_task(item_id)

@bp.route("/tasks/<int:item_id>", methods=["DELETE"])
def delete_task_alt(item_id):
    return delete_task(item_id)
